 Check((await Js("window.orbitReady===true")).GetBoolean(),"Real React frontend initialized");Check((await Js("document.querySelectorAll('.ht').length===3")).GetBoolean(),"Copied HubTile components rendered");Check((await Js("document.querySelectorAll('canvas').length===2")).GetBoolean(),"Scene and Mine3D character canvases exist");Check((await Js("document.querySelectorAll('.orbit-error').length===0 && window.orbitErrors.length===0")).GetBoolean(),"No frontend or character errors");Check((await Js("document.querySelector('#playBtn').getBoundingClientRect().width>180")).GetBoolean(),"PLAY is visibly rendered");await Capture("millida-home");Check((await Js("window.orbitState.icons.forge.startsWith('data:image/png')&&window.orbitState.icons.fabric.startsWith('data:image/png')")).GetBoolean(),"Forge anvil and official Fabric logo embedded");await Click(".lobby-mode");Check((await Js("!!document.querySelector('.orbit-version-picker')")).GetBoolean(),"Version picker opens from the mode button");await Click(".lobby-mode");Check((await Js("!document.querySelector('.orbit-version-picker')")).GetBoolean(),"Same mode button closes version picker");
 await Click(".lobby-mode");await Click(".orbit-quick-actions .forge");Check((await Js("!!document.querySelector('[aria-label=\"Quick loader\"]') && document.body.innerText.includes('Forge')")).GetBoolean(),"Forge quick-install dialog opens without starting installation");await Capture("quick-forge-dialog");await Click(".orbit-close");
