 await Js("window.chrome.webview.postMessage({action:'navigate',page:'Library'})");await Task.Delay(700);Check(page=="Library"&&(await Js("!!document.querySelector('.orbit-grid')")).GetBoolean(),"Library navigation reaches native instance data");Check((await Js("(()=>{const forge=document.querySelector('.orbit-card.forge'),fabric=document.querySelector('.orbit-card.fabric'),vanilla=document.querySelector('.orbit-card.installed');return forge&&fabric&&vanilla&&getComputedStyle(forge).backgroundColor==='rgb(169, 179, 191)'&&getComputedStyle(fabric).backgroundColor==='rgb(191, 141, 86)'&&getComputedStyle(vanilla).backgroundColor==='rgb(40, 120, 76)'})()")).GetBoolean(),"Forge grey, Fabric brown and installed green actually rendered");await Click(".orbit-card.fabric .orbit-pick");Check(SelectedChoice?.Loader=="Fabric"&&(await Js("window.orbitState.selectedKind==='fabric'")).GetBoolean(),"Fabric card selects the real native instance");await Capture("millida-library");
